export function getLabelByKey<T, K extends keyof T, L extends keyof T>(
  items: readonly T[],
  targetValue: T[K] | null | undefined,
  keyField: K,
  labelField: L,
): string {
  if (targetValue === null || targetValue === undefined) {
    return '-'
  }

  const found = items.find((item) => item[keyField] === targetValue)

  return found ? String(found[labelField]) : '-'
}

