const transformConditionText = (condition: GroupConditionForm) => {
  const {
    value: { type, value, option, label },
    options,
    selectItems = [],
  } = condition;
  const getValue = () => {
    if (type === 'text') return String(value);
    if (type === 'number') return Number(value);
    if (type === 'date') return toFormatDate(value, 'YYYY年MM月DD日');
    if (type === 'select')
      return getLabelFromOptions(selectItems, Number(value));

    return '';
  };

  return `${label}が 「${getValue()}」 ${getLabelFromOptions(
    options,
    option.value,
  )}`;
};

